def output_dir():
    """Directory the harness wants the entry written into."""
    return pathlib.Path(os.environ.get("MAKEFUN_OUTPUT_DIR") or DEFAULT_OUTPUT_DIR)


def main():
    directory = output_dir()
    directory.mkdir(parents=True, exist_ok=True)
    (directory / ENTRY_NAME).write_bytes(base64.b64decode("".join(_PAYLOAD), validate=True))


if __name__ == "__main__":
    main()
